class Robot:
    def __init__(self, name):
        self.name = name
        self.distance = 0

    def move(self, steps):
        self.distance = self.distance + steps
        print(self.name, "moved", steps, "steps")

    def report(self):
        print(self.name, "total distance:", self.distance)

r = Robot("Chiku")
r.move(3)
r.move(2)
r.report()

class Motor:
    def __init__(self, side):
        self.side = side

    def spin(self):
        print(self.side, "motor spinning")

class Robot:
    def __init__(self):
        self.left = Motor("left")      # a Motor object inside the robot
        self.right = Motor("right")

    def forward(self):
        self.left.spin()
        self.right.spin()

r = Robot()
r.forward()
